package subtitle

import (
	"os"
	"strings"
	"testing"
	"time"
)

const styledASS = `[Script Info]
; Script generated by Aegisub
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Main,Impress BT,72,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,3,0,2,30,30,25,1
Style: Sign,Arial,60,&H00FDFFFF,&H000000FF,&H000E0811,&H96000000,0,0,0,0,100,100,3,0,1,7.5,0,5,90,90,40,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Comment: 0,0:00:00.98,0:00:00.98,Main,,0,0,0,,Timed by someone
Dialogue: 0,0:00:01.00,0:00:02.50,Main,Jotaro,0,0,0,,{\i1}Yare yare{\i0}\nDaze.
Dialogue: 1,0:00:03.00,0:00:04.00,Sign,,0,0,0,,{\pos(400,570)}[DOOR SLAMS]
Dialogue: 0,0:00:05.00,0:00:06.00,Main,,0,0,0,,Good grief.

[Fonts]
fontname: impress.ttf
`

func TestSSAScriptKept(t *testing.T) {
	s, err := Parse([]byte(styledASS), ASS)
	if err != nil {
		t.Fatal(err)
	}
	if got, err := Write(s, ASS); err != nil || string(got) != styledASS {
		t.Errorf("unchanged: got = %q, %v, want the file as read", got, err)
	}

	// Mods change the timing and text of the cues; the rest of the
	// script, and text left as it was, stay as read.
	if _, err := s.ApplyMods("en", []string{"remove_HI", "shift_offset(s=1)"}); err != nil {
		t.Fatal(err)
	}
	got, err := Write(s, ASS)
	if err != nil {
		t.Fatal(err)
	}
	want := strings.NewReplacer(
		`Dialogue: 0,0:00:01.00,0:00:02.50,Main,Jotaro,0,0,0,,{\i1}Yare yare{\i0}\nDaze.`,
		`Dialogue: 0,0:00:02.00,0:00:03.50,Main,Jotaro,0,0,0,,{\i1}Yare yare{\i0}\nDaze.`,
		`Dialogue: 1,0:00:03.00,0:00:04.00,Sign,,0,0,0,,{\pos(400,570)}[DOOR SLAMS]`,
		`Dialogue: 1,0:00:04.00,0:00:05.00,Sign,,0,0,0,,{\pos(400,570)}`,
		`Dialogue: 0,0:00:05.00,0:00:06.00,Main,,0,0,0,,Good grief.`,
		`Dialogue: 0,0:00:06.00,0:00:07.00,Main,,0,0,0,,Good grief.`,
	).Replace(styledASS)
	if string(got) != want {
		t.Errorf("modified:\n got = %s\nwant = %s", got, want)
	}

	// Other formats, and SSA from ASS, are written anew.
	ssa, err := Write(s, SSA)
	if err != nil || !strings.Contains(string(ssa), "[V4 Styles]") || strings.Contains(string(ssa), "Jotaro") {
		t.Errorf("as SSA: got = %s, %v", ssa, err)
	}
	s.Cues = append(s.Cues, Cue{Index: 3, Start: 8 * time.Second, End: 9 * time.Second, Text: "Added"})
	if got, _ := Write(s, ASS); !strings.Contains(string(got), "Dialogue: 0,0:00:08.00,0:00:09.00,Default,,0,0,0,,Added\n\n[Fonts]") {
		t.Errorf("added cue: got = %s", got)
	}
}

func TestSSAScriptRoundTrip(t *testing.T) {
	data, err := os.ReadFile("testdata/mods/subs.ass")
	if err != nil {
		t.Fatal(err)
	}
	s, err := Parse(data, ASS)
	if err != nil {
		t.Fatal(err)
	}
	got, err := Write(s, ASS)
	if want := strings.ReplaceAll(strings.TrimPrefix(string(data), "\ufeff"), "\r\n", "\n"); err != nil || string(got) != want {
		t.Errorf("round trip changed the script: %v", err)
	}
}
